'use strict';
/* Prospecting group: find buyers, seller and re-listing opportunities, new developments, market updates, CMA,
   AI voice caller, campaign setup, voice agents, campaign manager. Prefix cwPs. */
function cwPsEnsure(){const c=state.cw;if(!c.psSaved)c.psSaved=[];if(!c.mu.reports)c.mu.reports=[];if(!c.mu.recurring)c.mu.recurring=[];if(!c.psOrders)c.psOrders=[];if(!c.psSetup)c.psSetup={step:0,v:{}};if(!c.landchecker)c.landchecker={on:true,limit:500,calls:[]}}
function cwPsNear(sub,radius){const r=Number(radius)||2;const s=new Set([sub]);if(r>=5)(CW_NEAR[sub]||[]).forEach(x=>s.add(x));if(r>=15)for(const x of [...s])(CW_NEAR[x]||[]).forEach(y=>s.add(y));return [...s]}
function cwPsLive(d){return d&&d.active&&['For sale','Listed'].includes(d.stage)}

/* ---------- Find buyers ---------- */
function cwPsBuyerSearch(){const d=findD(cwF('cwPs:fbdeal',''));const x=d?cwDX(d):null;
 const sub=cwF('cwPs:fbsub',d?.suburb||''),pmin=Number(cwF('cwPs:fbpmin',x?Math.round(x.priceLow*0.9):0))||0,pmax=Number(cwF('cwPs:fbpmax',x?Math.round(x.priceHigh*1.1):0))||0,bmin=Number(cwF('cwPs:fbbmin',x?Math.max(1,x.beds-1):0))||0,bamin=Number(cwF('cwPs:fbbamin',0))||0,cmin=Number(cwF('cwPs:fbcmin',0))||0,rad=cwF('cwPs:fbrad','5 km');
 const subs=sub?cwPsNear(sub,parseInt(rad)):[];
 const sig=d&&typeof gvxMatchBuyers==='function'?gvxMatchBuyers(d):[];
 const out=[];
 for(const p of cwContacts().filter(p=>p.role!=='seller')){const pr=cwPX(p).prefs;if(!pr||pr.inactive)continue;const why=[];let score=0;
  if(subs.length&&(pr.suburbs||[]).some(s=>subs.includes(s))){why.push('Looking in '+(pr.suburbs||[]).filter(s=>subs.includes(s)).join(', '));score+=3}else if(subs.length)continue;
  if(pmax&&pr.priceMin>pmax||pmin&&pr.priceMax<pmin)continue;if(pmin||pmax){why.push('Budget '+cwShort(pr.priceMin)+' to '+cwShort(pr.priceMax));score+=2}
  if(bmin&&pr.beds<bmin&&pr.beds)continue;if(bamin&&pr.baths&&pr.baths<bamin)continue;if(cmin&&pr.cars&&pr.cars<cmin)continue;
  const s=sig.find(z=>z.p.id===p.id);if(s){why.push(...s.why);score+=s.score}
  out.push({p,why,score,liveOffer:!!s?.liveOffer})}
 for(const s of sig)if(!out.some(o=>o.p.id===s.p.id))out.push({p:s.p,why:s.why,score:s.score,liveOffer:s.liveOffer});
 return{d,out:out.sort((a,b)=>b.score-a.score)}}
cwPage('/prospecting/find-buyers',{title:'Find buyers',group:'prosp',render(){
 const {d,out}=cwPsBuyerSearch();const x=d?cwDX(d):null;const live=cwPsLive(d);
 const props=[['','Choose a property'],...cwProps().filter(p=>p.active).map(p=>[p.id,cwAddr(p)])];
 const lbl=(k,l,def)=>`<label class="cw-ff"><span class="form-label">${l}</span>${cwInput(k,'',{cls:'full',type:'number',def:def,label:l})}</label>`;
 return `${cwHeader('Find Buyers for a Property','Who in the CRM fits a property, from recorded preferences and what they have done. Strongest first.')}
 ${cwCard('1 · Property',`<div class="cw-grid"><label class="cw-ff full"><span class="form-label">Property</span>${cwSelect('cwPs:fbdeal',props,{label:'Property',cls:'full'})}</label><label class="cw-ff"><span class="form-label">Suburb</span>${cwInput('cwPs:fbsub','Suburb',{cls:'full',def:d?.suburb||''})}</label><label class="cw-ff"><span class="form-label">State</span><input class="field full" value="VIC" disabled aria-label="State"></label>
 ${lbl('cwPs:fbpmin','Price from ($)',x?Math.round(x.priceLow*0.9):'')}${lbl('cwPs:fbpmax','Price to ($)',x?Math.round(x.priceHigh*1.1):'')}${lbl('cwPs:fbbmin','Bedrooms at least',x?Math.max(1,x.beds-1):'')}${lbl('cwPs:fbbamin','Bathrooms at least','')}${lbl('cwPs:fbcmin','Car spaces at least','')}<label class="cw-ff"><span class="form-label">Radius</span>${cwSelect('cwPs:fbrad',['2 km','5 km','10 km','15 km','25 km'],{def:'5 km',label:'Radius',cls:'full'})}</label></div>`)}
 ${cwStats([['Matches',out.length],['Can be contacted',out.filter(o=>!cwOptedOut(o.p)).length],['Live offer, call only',out.filter(o=>o.liveOffer).length],['No longer looking',cwContacts().filter(p=>cwPX(p).prefs?.inactive).length]])}
 ${cwCard('Buyer search status',d?(!live?cwNote(h(d.address)+' is not advertised ('+h(d.stage)+'), so GeeVee will not draft messages about it. You can still call.','warn'):'')+cwTable('cwPsFb',[['Buyer',o=>cwLdWho(o.p),o=>o.p.name],['Why they match',o=>`<ul class="bullet small">${o.why.map(w=>`<li>${h(w)}</li>`).join('')}</ul>`,o=>o.score],['Intent',o=>tag(cwPX(o.p).prefs?.intent||'unknown','outline')],['',o=>cwOptedOut(o.p)?tag('Opted out. Do not contact.','red'):`<div class="cw-row">${cwBtn('Call','call',o.p.id,'sm primary')}${!o.liveOffer&&live?cwBtn('Draft text','cwPsFbDraft',o.p.id,'sm'):o.liveOffer?tag('Live offer, call only','yellow'):''}${cwBtn('No longer looking','cwPsFbStop',o.p.id,'sm ghost')}</div>`]],out,{key:o=>o.p.id,empty:'No buyers match',emptyBody:'Widen the radius or the price range.'}):cwEmpty('Choose a property','Pick one of your properties to see which buyers fit it.'))}`},
 ai(){const {d,out}=cwPsBuyerSearch();const ok=out.filter(o=>!cwOptedOut(o.p)&&!o.liveOffer);return d?[{k:'info',t:out.length+' buyers fit '+h(d.address),b:'Ranked by what they did (offer, enquiry, views) before what they told us (suburb, budget). Budgets come from recorded preferences.'},cwPsLive(d)&&ok.length?{k:'draft',t:'Draft a text to '+ok.length+' buyers',b:'Each draft goes to Today for approval. Opted-out buyers and buyers with a live offer are skipped.',a:[['Draft all','cwPsFbDraftAll','','primary']]}:null]:[{k:'info',t:'Choose a property',b:'GeeVee then lists buyers with a recorded reason to hear about it.'}]}});
function cwPsDraftBuyer(p,d){if(!p||!d||cwOptedOut(p)||state.actions.some(a=>a.contactId===p.id&&a.dealId===d.id&&a.status==='Awaiting review'))return false;const dr=typeof gvxBuyerDraft==='function'?gvxBuyerDraft(p,d,'SMS'):{body:'Hi '+p.name.split(' ')[0]+', '+d.address+' may suit you. Caleb, Collings. Reply STOP to opt out.'};addAction({type:'SMS',title:'Buyer match: '+d.address+' to '+p.name,body:dr.body,contactId:p.id,dealId:d.id,tier:'A2'});return true}
cwOn('cwPsFbDraft',pid=>{const d=findD(cwF('cwPs:fbdeal',''));cwPersist(cwPsDraftBuyer(findP(pid),d)?'Draft is on Today for your approval. Nothing was sent.':'A draft already exists or this buyer cannot be contacted.')});
cwOn('cwPsFbDraftAll',()=>{const {d,out}=cwPsBuyerSearch();let n=0;for(const o of out)if(!o.liveOffer&&cwPsDraftBuyer(o.p,d))n++;cwPersist(n+' drafts on Today for approval.')});
cwOn('cwPsFbStop',pid=>{const p=findP(pid);if(!p)return;const x=cwPX(p);x.prefs={...(x.prefs||{}),inactive:true};cwContactHistory(p,'Marked no longer looking');cwPersist(p.name+' marked no longer looking.')});

/* ---------- Seller opportunities ---------- */
function cwPsOpps(){const out=[];const buyersFor=(sub,price)=>cwContacts().filter(p=>{const pr=cwPX(p).prefs;return pr&&!pr.inactive&&(pr.suburbs||[]).includes(sub)&&(!price||(pr.priceMin<=price*1.1&&pr.priceMax>=price*0.9))}).length;
 for(const d of cwProps()){const p=findP(d.contactId);let kind=null;if(d.stage==='Lost')kind='Withdrawn or expired';else if(d.stage==='Sold')kind='Our past listings';else if(['Appraisal','Proposal'].includes(d.stage))kind='Appraised';else if(d.stage==='New lead')kind='Seller leads';else if(d.stage==='For sale'&&cwDX(d).dom>40)kind='Our price reductions';if(!kind)continue;
  out.push({key:'d:'+d.id,address:d.address,suburb:d.suburb,price:d.guide,kind,owner:p?.name||'',ownerId:p?.id||null,phone:p?.phone||'',agent:cwDX(d).agents[0]||d.owner||'',dealId:d.id,buyers:buyersFor(d.suburb,d.guide)})}
 for(const r of state.cw.relisting)out.push({key:'r:'+r.id,address:r.address,suburb:r.suburb,price:r.price,kind:r.agency.startsWith('Collings')?'Withdrawn or expired':'Price cut elsewhere',owner:r.owner||'',ownerId:r.ownerId,phone:findP(r.ownerId)?.phone||'',agent:r.ownerId?findP(r.ownerId)?.owner||'':'',buyers:buyersFor(r.suburb,r.price)});
 return out.map(o=>({...o,st:state.cw.oppStatus[o.key]||{},actionable:!!(o.ownerId&&o.phone&&!cwOptedOut(findP(o.ownerId)))})).filter(o=>o.buyers>0||o.kind==='Seller leads'||o.kind==='Appraised')}
const CW_PS_FUNNEL=['Identified','Owner contacted','Owner interested','Appraisal booked','Listing secured','Sold'];
function cwPsOppTab(o){const s=o.st.status||'To action';if(s==='Closed')return 'Closed';if(s==='Progressed')return 'Progressed';if(s==='Follow-up booked')return 'Follow-up booked';return 'To action'}
cwPage('/prospecting/seller-opportunities',{title:'Seller opportunities',group:'prosp',render(){
 const all=cwPsOpps(),tab=cwTab('cwPsSo','To action'),act=cwF('cwPs:soact','Actionable and to verify'),kind=cwF('cwPs:sokind','All kinds'),ag=cwF('cwPs:soag','All agents'),q=cwF('cwPs:soq','');
 const inTab=o=>tab==='All agency'?true:tab==='Unassigned'?!o.agent:cwPsOppTab(o)===tab&&(o.agent===CW_ME||!o.agent&&tab!=='To action'||o.agent===CW_ME);
 let list=all.filter(o=>inTab(o)&&(act==='Actionable and to verify'||(act==='Actionable'?o.actionable:!o.actionable))&&(kind==='All kinds'||o.kind===kind)&&(ag==='All agents'||o.agent===ag));list=cwSearchRows(list,q,o=>o.address+' '+o.suburb+' '+o.owner);
 list.sort((a,b)=>(b.actionable-a.actionable)||b.buyers-a.buyers);
 const fun=CW_PS_FUNNEL.map(f=>[f,all.filter(o=>CW_PS_FUNNEL.indexOf(o.st.funnel||'Identified')>=CW_PS_FUNNEL.indexOf(f)).length]);
 const tabs=['To action','Follow-up booked','Unassigned','All agency','Progressed','Closed'];
 return `${cwHeader('Seller Opportunities','Properties worth a call because we already hold buyers for them: withdrawn and expired listings, our past listings, appraisals, seller leads and price cuts, most actionable first. Each one goes to the agent who holds the owner; everyone can see the whole agency under All agency.',cwBtn('Preview report-only','cwPsSoReport','',''))}
 ${cwStats(fun.map(([l,n])=>[l,n]),'grid-3')}
 <div class="toolbar">${cwTabs('cwPsSo',tabs.map(t=>[t,t,all.filter(o=>t==='All agency'?true:t==='Unassigned'?!o.agent:cwPsOppTab(o)===t).length]))}</div>
 <div class="toolbar">${cwSelect('cwPs:soact',['Actionable and to verify','Actionable','Needs verification'],{label:'Actionable'})}${cwSelect('cwPs:sokind',['All kinds','Withdrawn or expired','Our past listings','Appraised','Seller leads','Price cut elsewhere','Our price reductions'],{label:'Kind'})}${cwSelect('cwPs:soag',['All agents',...cwAgentNames()],{label:'Agent'})}${cwInput('cwPs:soq','Search address or suburb')}</div>
 ${cwTable('cwPsSoT',[['Property',o=>`<b>${h(o.address)}, ${h(o.suburb)}</b><div class="tiny muted">${o.price?cwShort(o.price):''}</div>`,o=>o.address],['Kind',o=>tag(o.kind,'outline')],['Owner',o=>o.owner?`${h(o.owner)}<div class="tiny muted">${h(o.phone||'No mobile on file')}</div>`:'<span class="muted">No owner on file</span>'],['Buyers we hold',o=>`<b>${o.buyers}</b>`,o=>o.buyers],['Agent',o=>h(o.agent||'Unassigned')],['Stage',o=>tag(o.st.funnel||'Identified','teal')],['Status',o=>o.actionable?tag('Actionable','green'):tag('Needs verification','yellow')],
  ['',o=>`<div class="cw-row">${o.ownerId&&o.actionable?cwBtn('Call','call',o.ownerId,'sm primary'):''}${cwBtn('Log','cwPsSoLog',o.key,'sm')}${!o.agent?cwBtn('Assign to me','cwPsSoMine',o.key,'sm'):''}${cwBtn('Follow-up','cwPsSoFollow',o.key,'sm')}${o.st.status==='Closed'?cwBtn('Reopen','cwPsSoSet',o.key+'|To action','sm'):cwBtn('Close','cwPsSoSet',o.key+'|Closed','sm ghost')}</div>`]],list,{key:o=>o.key,empty:'Nothing to action',emptyBody:'Opportunities appear when we hold buyers for a property.'})}`},
 ai(){const a=cwPsOpps().filter(o=>o.actionable&&cwPsOppTab(o)==='To action');return[a.length?{k:'call',t:a.length+' owners worth a call',b:'Top: '+h(a.sort((x,y)=>y.buyers-x.buyers)[0].address)+' ('+a[0].buyers+' buyers). Owners get a call from you, never a message from GeeVee.',a:[['Call first','call',a[0].ownerId,'primary']]}:{k:'info',t:'Nothing actionable right now'},{k:'info',t:'Needs verification',b:'Owners without a mobile or with no permission evidence need checking first, including a Do Not Call check.'}]}});
function cwPsOppSet(key,patch){state.cw.oppStatus[key]={...(state.cw.oppStatus[key]||{}),...patch,at:cwNowISO()}}
cwOn('cwPsSoSet',k=>{const [key,s]=k.split('|');cwPsOppSet(key,{status:s});cwPersist(s==='Closed'?'Closed.':'Reopened.')});
cwOn('cwPsSoMine',key=>{const o=cwPsOpps().find(x=>x.key===key);if(o?.dealId)cwDX(findD(o.dealId)).agents[0]=CW_ME;cwPsOppSet(key,{agent:CW_ME});if(o&&!o.agent&&o.key.startsWith('r:')){const r=state.cw.relisting.find(x=>'r:'+x.id===key);if(r&&r.ownerId){const p=findP(r.ownerId);if(p)p.owner=CW_ME}}cwPersist('Assigned to you.')});
cwOn('cwPsSoLog',key=>cwModal('cwPsSoLog',key));
cwModalDef('cwPsSoLog',key=>{const o=cwPsOpps().find(x=>x.key===key);return{title:'Log progress: '+(o?.address||''),body:cwForm('cwPsSL',[{n:'funnel',l:'Where is it at?',t:'select',o:CW_PS_FUNNEL},{n:'note',l:'Note',t:'textarea'}],{funnel:o?.st.funnel||'Owner contacted'}),foot:cwBtn('Cancel','close')+cwBtn('Save','cwPsSoLogSave',key,'primary')}});
cwOn('cwPsSoLogSave',key=>{const v=cwRead('cwPsSL',[{n:'funnel',l:'Stage',t:'select'},{n:'note',l:'Note',t:'textarea'}]);if(!v)return;const i=CW_PS_FUNNEL.indexOf(v.funnel);cwPsOppSet(key,{funnel:v.funnel,note:v.note,status:i>=3?'Progressed':'To action'});const o=cwPsOpps().find(x=>x.key===key);if(v.funnel==='Appraisal booked'&&o)state.cw.events.push({id:cwId('EV'),title:'Appraisal: '+o.address,start:cwDayISO(3,10),mins:60,where:o.address+', '+o.suburb,kind:'Appraisal',contactId:o.ownerId||'',dealId:o.dealId||''});ui.modal=null;cwPersist('Saved: '+v.funnel+'.')});
cwOn('cwPsSoFollow',key=>cwModal('cwPsSoFollow',key));
cwModalDef('cwPsSoFollow',key=>({title:'Book a follow-up',body:cwForm('cwPsSF',[{n:'date',l:'Call on',t:'date',req:true}],{date:cwLocalDay(new Date(Date.now()+7*864e5))}),foot:cwBtn('Cancel','close')+cwBtn('Book','cwPsSoFollowSave',key,'primary')}));
cwOn('cwPsSoFollowSave',key=>{const v=cwRead('cwPsSF',[{n:'date',l:'Date',t:'date',req:true}]);if(!v)return;const o=cwPsOpps().find(x=>x.key===key);cwPsOppSet(key,{status:'Follow-up booked',funnel:o?.st.funnel||'Owner contacted'});addTask({title:'Follow up owner: '+(o?.address||''),contactId:o?.ownerId||'',dealId:o?.dealId||'',due:cwDate(v.date),dueISO:v.date,priority:'Normal',category:'Call',origin:'GeeVee · seller opportunity'});ui.modal=null;cwPersist('Follow-up booked and added to Tasks.')});
cwOn('cwPsSoReport',()=>cwModal('cwPsSoReport'));
cwModalDef('cwPsSoReport',()=>{const all=cwPsOpps();const by={};all.forEach(o=>by[o.kind]=(by[o.kind]||0)+1);return{title:'Seller opportunities report',wide:'large',body:`<p class="small" style="margin-bottom:10px">Report only. Nothing changes from this view.</p>${cwKV(Object.entries(by).map(([k,n])=>[k,String(n)]))}<div class="sep"></div>${cwKV(CW_PS_FUNNEL.map(f=>[f,String(all.filter(o=>CW_PS_FUNNEL.indexOf(o.st.funnel||'Identified')>=CW_PS_FUNNEL.indexOf(f)).length)]))}`,foot:cwBtn('Print','cwPsPrint','','')+cwBtn('Close','close','','primary')}});
cwOn('cwPsPrint',()=>{try{window.print()}catch(e){}});

/* ---------- Re-listing ---------- */
cwPage('/prospecting/relisting-opportunities',{title:'Re-listing opportunities',group:'prosp',render(){
 const kind=cwF('cwPs:rlk','All'),sort=cwF('cwPs:rls','Most recent first'),sub=cwF('cwPs:rlsub',''),from=cwF('cwPs:rlfrom',''),to=cwF('cwPs:rlto','');
 const bm=r=>cwContacts().filter(p=>{const pr=cwPX(p).prefs;return pr&&!pr.inactive&&(pr.suburbs||[]).includes(r.suburb)&&pr.priceMin<=r.price*1.1&&pr.priceMax>=r.price*0.9}).length;
 let list=state.cw.relisting.filter(r=>(kind==='All'||r.kind===kind)&&(!sub||r.suburb.toLowerCase().includes(sub.toLowerCase()))&&(!from||cwLocalDay(r.date)>=from)&&(!to||cwLocalDay(r.date)<=to));
 const sorts={'Most recent first':(a,b)=>Date.parse(b.date)-Date.parse(a.date),'Longest on market':(a,b)=>b.dom-a.dom,'Price high to low':(a,b)=>b.price-a.price,'Price low to high':(a,b)=>a.price-b.price,'Suburb A to Z':(a,b)=>a.suburb.localeCompare(b.suburb),'Best buyer match':(a,b)=>bm(b)-bm(a)};list.sort(sorts[sort]);
 const all=state.cw.relisting;
 return `${cwHeader('Re-listing Opportunities','Competitor listings withdrawn and not back on the market, listings 60+ days on market, and the office\'s expired listings, with owner details from our records. Find Buyers shows who in the CRM fits a property; Add Lead puts the owner on Prospects.')}
 <div class="toolbar">${cwPills('cwPs:rlk',[['All','All',all.length],['Withdrawn','Withdrawn',all.filter(r=>r.kind==='Withdrawn').length],['60+ days on market','60+ days on market',all.filter(r=>r.kind==='60+ days on market').length]])}</div>
 <div class="toolbar">${cwInput('cwPs:rlsub','Search suburbs')}<label class="tiny muted">From ${cwInput('cwPs:rlfrom','',{type:'date',cls:'cw-mini',label:'From date'})}</label><label class="tiny muted">To ${cwInput('cwPs:rlto','',{type:'date',cls:'cw-mini',label:'To date'})}</label>${cwSelect('cwPs:rls',Object.keys(sorts),{label:'Sort'})}</div>
 ${cwTable('cwPsRl',[['Property',r=>`<b>${h(r.address)}, ${h(r.suburb)}</b>`,r=>r.address],['Kind',r=>tag(r.kind,r.kind==='Withdrawn'?'red':'yellow')],['Agency',r=>h(r.agency)],['Last price',r=>cwShort(r.price),r=>r.price],['Days on market',r=>r.dom,r=>r.dom],['Date',r=>cwDate(r.date),r=>r.date],['Buyers who fit',r=>`<b>${bm(r)}</b>`,bm],['',r=>`<div class="cw-row">${cwBtn('Owner details','cwPsRlOwner',r.id,'sm')}${cwBtn('Find buyers','cwPsRlBuyers',r.id,'sm')}${r.leadId?cwGoBtn('On Prospects','/prospects','sm'):cwBtn('Add lead','cwPsRlLead',r.id,'sm primary')}</div>`]],list,{empty:'No re-listing opportunities',emptyBody:'Withdrawn and long-running listings in your suburbs appear here.'})}`},
 ai(){const n=state.cw.relisting.filter(r=>!r.ownerId).length,ok=state.cw.relisting.filter(r=>r.ownerId&&!r.leadId);return[ok.length?{k:'call',t:ok.length+' owners on file',b:'Add them as leads and call. A withdrawn listing often means the owner still wants to sell.'}:null,n?{k:'check',t:n+' without owner details',b:'Check the Database or the title before contacting anyone.'}:null]}});
cwOn('cwPsRlOwner',id=>cwModal('cwPsRlOwner',id));
cwModalDef('cwPsRlOwner',id=>{const r=state.cw.relisting.find(x=>x.id===id),p=findP(r?.ownerId),db=state.cw.db.records.find(x=>x.address.toLowerCase()===String(r?.address).toLowerCase());return{title:'Owner details: '+(r?.address||''),body:p?cwKV([['Owner',h(p.name)],['Mobile',h(p.phone)],['Email',h(p.email)],['Permission',cwOptedOut(p)?'Do not contact':h(cwPX(p).permission?.evidence||'')]]):db?cwKV([['Owner',h(db.owner)],['Mobile',h(db.mobile)],['From','Database']]):'<p class="small">No owner on file. Check the Database or a title search before contacting anyone.</p>',foot:(p?cwGoBtn('Open contact','/contacts/'+p.id,''):'')+cwBtn('Close','close','','primary')}});
cwOn('cwPsRlBuyers',id=>{const r=state.cw.relisting.find(x=>x.id===id);if(!r)return;cwSetF('cwPs:fbdeal','');cwSetF('cwPs:fbsub',r.suburb);cwSetF('cwPs:fbpmin',Math.round(r.price*0.9));cwSetF('cwPs:fbpmax',Math.round(r.price*1.1));cwGo('/prospecting/find-buyers')});
cwOn('cwPsRlLead',id=>{const r=state.cw.relisting.find(x=>x.id===id);if(!r)return;let p=findP(r.ownerId);if(!p){cwModal('cwPsRlNoOwner',id);return}const d=cwLdNewDeal({contactId:p.id,address:r.address,suburb:r.suburb,guide:r.price,stage:'New lead',source:'Re-listing',why:r.kind+' listing',next:'Call owner',via:'re-listing opportunities',cw:{market:'Off market'}});r.leadId=d.id;cwPersist('Added to Prospects. Call the owner from there.')});
cwModalDef('cwPsRlNoOwner',id=>({title:'Owner needed',body:'<p class="small">There is no owner on file for this property. Add the owner to the Database first, with permission evidence, then add the lead.</p>',foot:cwGoBtn('Open Database','/database','primary')}));

/* ---------- New developments ---------- */
cwPage('/prospecting/new-developments',{title:'New developments',group:'prosp',render(){cwPsEnsure();
 const tab=cwTab('cwPsDv','All'),sort=cwF('cwPs:dvs','Recently updated'),sub=cwF('cwPs:dvsub',''),kw=cwF('cwPs:dvkw',''),stage=cwF('cwPs:dvst','Any stage'),minv=Number(cwF('cwPs:dvmin',''))||0;
 const all=state.cw.developments;let list=all.filter(x=>(tab==='All'?x.status!=='Abandoned':x.status==='Abandoned')&&(!sub||x.suburb.toLowerCase().includes(sub.toLowerCase()))&&(!kw||(x.name+' '+x.companies).toLowerCase().includes(kw.toLowerCase()))&&(stage==='Any stage'||x.stage===stage)&&x.value>=minv);
 const sorts={'Recently updated':(a,b)=>Date.parse(b.updated)-Date.parse(a.updated),'Construction start, soonest':(a,b)=>(a.start||'9')<(b.start||'9')?-1:1,'Value high to low':(a,b)=>b.value-a.value,'Value low to high':(a,b)=>a.value-b.value,'Most units':(a,b)=>b.units-a.units,'Suburb A to Z':(a,b)=>a.suburb.localeCompare(b.suburb)};list.sort(sorts[sort]);
 return `${cwHeader('New Developments','Upcoming construction projects in our suburbs from BCI, with the companies behind each one where BCI lists them. Click a project to see everything BCI has on it.')}
 <div class="cw-side"><div class="card pad"><h3 style="margin-bottom:10px">Filters</h3><div class="cw-form">${cwInput('cwPs:dvkw','Keyword(s)',{cls:'full'})}${cwInput('cwPs:dvsub','Project location (suburb)',{cls:'full'})}${cwSelect('cwPs:dvst',['Any stage',...new Set(all.map(x=>x.stage))],{label:'Stage & status',cls:'full'})}${cwInput('cwPs:dvmin','Minimum project value ($)',{cls:'full',type:'number'})}<div class="cw-row">${cwBtn('Clear all','cwPsDvClear','','sm')}${cwBtn('Save search','cwPsDvSave','','sm primary')}</div></div><div class="sep"></div><h3 style="margin-bottom:8px">Saved searches</h3>${state.cw.psSaved.map(s=>`<div class="cw-row between" style="margin-bottom:6px"><button type="button" class="table-btn" data-action="cwPsDvApply" data-id="${h(s.id)}">${h(s.name)}</button>${cwBtn('Delete','cwPsDvDel',s.id,'sm ghost')}</div>`).join('')||'<p class="hint">No saved searches yet. Pick your filters, then save them.</p>'}</div>
 <div class="cw-main"><div class="toolbar">${cwTabs('cwPsDv',[['All','All',all.filter(x=>x.status!=='Abandoned').length],['Abandoned','Abandoned',all.filter(x=>x.status==='Abandoned').length]])}${cwSelect('cwPs:dvs',Object.keys(sorts),{label:'Sort'})}</div>
 ${cwTable('cwPsDvT',[['Project',x=>`<button type="button" class="table-btn" data-action="cwPsDvOpen" data-id="${h(x.id)}">${h(x.name)}</button>`,x=>x.name],['Suburb',x=>h(x.suburb)],['Value',x=>cwShort(x.value),x=>x.value],['Units',x=>x.units,x=>x.units],['Stage',x=>tag(x.stage,x.stage==='Abandoned'?'red':'teal')],['Start',x=>x.start?cwDate(x.start):'Not set'],['Updated',x=>cwDate(x.updated)],['',x=>cwBtn('Owner details','cwPsDvOpen',x.id,'sm')]],list,{empty:'No projects found'})}</div></div>`},
 ai(){const s=state.cw.developments.filter(x=>x.status==='Active'&&x.start&&Date.parse(x.start)<Date.now()+90*864e5);return[s.length?{k:'info',t:s.length+' projects starting within 90 days',b:'Neighbours of a new build often think about selling. GeeVee can add a door-knock task for the street.',a:[['Add door knock tasks','cwPsDvKnock','']]}:null]}});
cwOn('cwPsDvClear',()=>{['cwPs:dvkw','cwPs:dvsub','cwPs:dvst','cwPs:dvmin'].forEach(k=>delete cwU().f[k]);render()});
