cwModalDef('cwPsDvOpen',id=>{const x=state.cw.developments.find(d=>d.id===id);return{title:x?.name||'Project',wide:'large',body:cwKV([['Suburb',h(x.suburb)],['Project value',cwMoney(x.value)],['Units',String(x.units)],['Stage',h(x.stage)],['Construction start',x.start?cwDate(x.start):'Not set'],['Last updated by BCI',cwDate(x.updated)],['Companies',h(x.companies)]])+`<div class="sep"></div><p class="hint">BCI data, read only. Contact company representatives by phone through their published business numbers.</p>`,foot:cwBtn(x.status==='Abandoned'?'Mark active':'Mark abandoned','cwPsDvAband',id,'')+cwBtn('Close','close','','primary')}});
