cwOn('cwPsDvKnock',()=>{let n=0;for(const x of state.cw.developments.filter(x=>x.status==='Active'&&x.start&&Date.parse(x.start)<Date.now()+90*864e5)){if(state.tasks.some(t=>t.cwPsDv===x.id))continue;addTask({title:'Door knock near '+x.name+', '+x.suburb,contactId:'',dealId:'',due:'This week',priority:'Normal',category:'Follow up',origin:'GeeVee · new development',cwPsDv:x.id});n++}cwPersist(n+' door knock tasks added.')});

