function cwPsMuOwners(){const src=cwF('cwPs:muSrc','All');const out=[];if(src!=='Database')for(const d of cwProps().filter(d=>['seller','both'].includes(findP(d.contactId)?.role))){const p=findP(d.contactId);out.push({key:'p:'+d.id,name:p.name,address:d.address,suburb:d.suburb,mobile:p.phone,email:p.email,src:'Pipeline',dnc:cwOptedOut(p),contactId:p.id,dealId:d.id,agent:cwDX(d).agents[0]||CW_ME})}
 if(src!=='Pipeline')for(const r of state.cw.db.records)out.push({key:'db:'+r.id,name:r.owner,address:r.address,suburb:r.suburb,mobile:r.mobile,email:r.email,src:'Database',dnc:r.dnc||r.permission!=='Has permission evidence',contactId:r.contactId||null,agent:r.agent||CW_ME});
 return out}
