cwOn('cwPsMuAssignGo',()=>{const v=cwRead('cwPsMA',[{n:'suburb',l:'Suburb',t:'select'},{n:'agent',l:'Agent',t:'select'}]);if(!v)return;let n=0;state.cw.db.records.filter(r=>r.suburb===v.suburb).forEach(r=>{r.agent=v.agent;n++});ui.modal=null;cwPersist(n+' owners in '+v.suburb+' assigned to '+v.agent+'.')});

