const CW_PS_MT_FIELDS=[{n:'name',l:'Template name',req:true},{n:'scope',l:'Visible to',t:'select',o:['My templates','Agency templates']},{n:'subject',l:'Subject',req:true,full:true},{n:'body',l:'Email body',t:'textarea',req:true}];
