function cwPsMuReport(id){cwPsEnsure();let r=state.cw.mu.reports.find(x=>x.id===id);if(!r&&String(id)==='1')r=state.cw.mu.reports[0]||cwPsMuCreate(cwPsMuOwners().find(o=>!o.dnc));return r}
cwPage('/prospecting/market-update/:id',{title:'Generate market update',group:'prosp',render(ctx){const r=cwPsMuReport(ctx.params.id);if(!r)return cwEmpty('Report not found','',cwGoBtn('Back to Market Update','/prospecting/market-update','primary'));
 const steps=['Vendor','Surrounding sales','Current listings'];const near=cwPsNear(r.v.suburb||'',10);
 let body='';
 if(r.step===0)body=cwForm('cwPsMuV',CW_PS_MU_FIELDS.map(f=>f.n==='template'?{...f,o:state.cw.mu.templates.map(t=>[t.id,t.name])}:f),r.v);
 else if(r.step===1){const sales=state.cw.sales.filter(s=>!r.v.suburb||near.includes(s.suburb));body=`<p class="small" style="margin-bottom:10px">Sales within about 10 km of ${h(r.v.suburb||'the property')}. Pick the ones to include.</p><div class="cw-ps-list">${(sales.length?sales:state.cw.sales).map(s=>`<label class="cw-ps-pick ${r.sales.includes(s.id)?'on':''}"><input type="checkbox" data-cwpsmusale="${h(r.id)}|${h(s.id)}" ${r.sales.includes(s.id)?'checked':''}><span><b>${h(s.address)}, ${h(s.suburb)}</b><small>${cwMoney(s.price)} · ${cwDate(s.date)} · ${s.beds} bed ${s.baths} bath</small></span></label>`).join('')}</div>`}
 else{const ls=cwProps().filter(d=>d.stage==='For sale');body=`<p class="small" style="margin-bottom:10px">Current listings to show. Prices shown as advertised.</p><div class="cw-ps-list">${ls.map(d=>`<label class="cw-ps-pick ${r.listings.includes(d.id)?'on':''}"><input type="checkbox" data-cwpsmulist="${h(r.id)}|${h(d.id)}" ${r.listings.includes(d.id)?'checked':''}><span><b>${h(d.address)}, ${h(d.suburb)}</b><small>${cwPrice(d)}</small></span></label>`).join('')}</div>`}
 return `${cwHeader('Generate market update',h((r.v.address||'New report')+(r.v.suburb?', '+r.v.suburb:'')),cwGoBtn('Back to Market Update','/prospecting/market-update',''))}
 ${cwSteps(steps,r.step)}${cwCard(steps[r.step]==='Vendor'?'Property and vendor':steps[r.step],`<div class="cw-step-body">${body}</div>`)}
 <div class="cw-row between">${r.step>0?cwBtn('Back','cwPsMuStep',r.id+'|-1',''):'<span></span>'}${r.step<2?cwBtn('Next','cwPsMuStep',r.id+'|1','primary'):r.status==='Draft'?cwBtn('Create report for approval','cwPsMuFinish',r.id,'primary'):tag(r.status,'yellow')}</div>`},
 ai(ctx){const r=cwPsMuReport(ctx.params.id);return[r?.status==='Draft'?{k:'draft',t:'Finishing sends nothing',b:'GeeVee builds the email with an unsubscribe line and puts it on Today. You approve it there.'}:{k:'info',t:'Waiting on Today',b:'This update is on Today for approval.',a:[['Open Today','route','today','primary']]}]}});
document.addEventListener('change',e=>{const el=e.target;if(!el?.dataset)return;const k=el.dataset.cwpsmusale||el.dataset.cwpsmulist||el.dataset.cwpscomp;if(!k)return;const [id,x]=k.split('|');
 if(el.dataset.cwpscomp){const c=state.cw.cma.find(z=>z.id===id);if(!c)return;c.comps=el.checked?[...new Set([...c.comps,x])]:c.comps.filter(z=>z!==x)}else{const r=state.cw.mu.reports.find(z=>z.id===id);if(!r)return;const arr=el.dataset.cwpsmusale?'sales':'listings';r[arr]=el.checked?[...new Set([...r[arr],x])]:r[arr].filter(z=>z!==x)}persist();render()});
cwOn('cwPsMuStep',k=>{const [id,dir]=k.split('|');const r=state.cw.mu.reports.find(x=>x.id===id);if(!r)return;if(r.step===0&&dir==='1'){const v=cwRead('cwPsMuV',CW_PS_MU_FIELDS);if(!v)return;r.v=v}if(r.step===1&&dir==='1'&&!r.sales.length){toast('Pick at least one sale.');return}r.step=Math.max(0,Math.min(2,r.step+Number(dir)));cwPersist()});
cwOn('cwPsMuFinish',id=>{const r=state.cw.mu.reports.find(x=>x.id===id);if(!r)return;const p=r.contactId?findP(r.contactId):state.people.find(x=>x.email&&x.email===r.v.email||x.phone&&x.phone===r.v.mobile);
 const db=state.cw.db.records.find(x=>x.address===r.v.address);if(p&&cwOptedOut(p)||db&&db.dnc){toast('This owner opted out or is do not contact. No update can be prepared.');return}
 const t=state.cw.mu.templates.find(x=>x.id===r.v.template)||state.cw.mu.templates[0];const sales=state.cw.sales.filter(s=>r.sales.includes(s.id)),ls=r.listings.map(findD).filter(Boolean);
 const body=`Hi ${r.v.first},\n\n${(t?.body||'').replace(/{{first_name}}/g,r.v.first).replace(/{{address}}/g,r.v.address).replace(/{{suburb}}/g,r.v.suburb).replace(/{{suburb_median}}/g,sales.length?cwMoney(sales.map(s=>s.price).sort((a,b)=>a-b)[Math.floor(sales.length/2)]):'not available')}\n\nRecent sales near you:\n${sales.map(s=>'- '+s.address+', '+s.suburb+': '+cwMoney(s.price)+' ('+cwDate(s.date)+')').join('\n')}${ls.length?'\n\nFor sale now:\n'+ls.map(d=>'- '+d.address+', '+d.suburb+': '+cwPrice(d)).join('\n'):''}\n\nCaleb Richards, Collings Real Estate\nTo stop these updates, reply unsubscribe or use the link below.`;
 addAction({type:'Email',title:'Market update for '+r.v.first+' '+(r.v.last||'')+', '+r.v.address,body,contactId:p?.id||'',dealId:'',tier:'A2'});r.status='Awaiting approval';audit('market update','Market update prepared: '+r.v.address,'Waiting on Today. Nothing sent.');cwPersist('Report is on Today for your approval. Nothing was sent.')});

/* ---------- CMA ---------- */
const CW_PS_CMA_KIND={sales:'Sales CMA',pps:'Property Price Statement',rental:'Rental CMA'};
cwPage('/prospecting/cma',{title:'CMA reports',group:'prosp',render(){
 const tab=cwTab('cwPsCma','sales'),kind=CW_PS_CMA_KIND[tab];
 const props=[['','Enter custom address'],...cwProps().filter(d=>d.active).map(d=>[d.id,cwAddr(d)])];
 const agent=cwF('cwPs:cmaag','Lead Agents'),exp=cwF('cwPs:cmaexp','Expiry');
 const reps=state.cw.cma.filter(c=>c.kind===kind&&(agent==='Lead Agents'||c.agent===agent)&&(exp==='Expiry'||c.status===exp||(exp==='Expiring soon'&&Date.parse(c.expiry)<Date.now()+7*864e5&&Date.parse(c.expiry)>Date.now())||(exp==='Expired'&&Date.parse(c.expiry)<Date.now())));
 const tabs=cwTabs('cwPsCma',[['sales','Sales CMA Report'],['pps','Property Price Statement'],['rental','Rental CMA Report']]);
 const help={sales:'Compare recent sales to price a property for a vendor.',pps:'The Section 47AF statement, published as a public link.',rental:'Compare leased properties to price a rental for a landlord.'}[tab];
 const opts=`${cwCard('Search options',`<p class="small muted" style="margin-bottom:10px">${help}</p><div class="cw-grid"><label class="cw-ff full"><span class="form-label">Target property</span>${cwSelect('cwPs:cmadeal',props,{cls:'full',label:'Target property'})}</label>${cwF('cwPs:cmadeal','')?'':`<label class="cw-ff full"><span class="form-label">Custom address</span>${cwInput('cwPs:cmaaddr','Enter a CMA Report target address...',{cls:'full'})}</label>`}<label class="cw-ff"><span class="form-label">Sale date from</span>${cwInput('cwPs:cmafrom','',{type:'date',cls:'full',label:'Sale date from'})}</label><label class="cw-ff"><span class="form-label">Sale date to</span>${cwInput('cwPs:cmato','',{type:'date',cls:'full',label:'Sale date to'})}</label><label class="cw-ff"><span class="form-label">Price from</span>${cwInput('cwPs:cmapmin','',{type:'number',cls:'full',label:'Price from'})}</label><label class="cw-ff"><span class="form-label">Price to</span>${cwInput('cwPs:cmapmax','',{type:'number',cls:'full',label:'Price to'})}</label><label class="cw-ff"><span class="form-label">Bedrooms from</span>${cwInput('cwPs:cmabmin','',{type:'number',cls:'full',label:'Bedrooms from'})}</label><label class="cw-ff"><span class="form-label">Property type</span>${cwSelect('cwPs:cmatype',['All Property Types','House','Apartment','Unit','Townhouse','Villa','Land','Blocks of units'],{cls:'full',label:'Property type'})}</label><div class="cw-ff">${cwCheck('cwPs:cmasur','Include surrounding suburbs',{def:true})}</div></div><div class="cw-row" style="margin-top:12px">${cwBtn('Quick set: last 6 months','cwPsCmaQuick','','sm')}${cwBtn('Start '+kind,'cwPsCmaStart',tab,'primary')}</div>`)}`;
 const pps=tab==='pps'?cwCard('Property Price Statements on file',cwTable('cwPsPps',[['Property',d=>cwLink(h(cwAddr(d)),'/properties/'+d.id+'?tab=documents')],['Indicative price',d=>cwPrice(d)],['Comparables',d=>cwDX(d).comps.length+' of 3'],['Statement',d=>cwDX(d).docs.pps.length?tag('On file','green'):tag('Missing','red')],['',d=>cwBtn('Prepare statement','cwPsPpsMake',d.id,'sm')]],cwProps().filter(d=>['For sale','Listed','Authority'].includes(d.stage)),{empty:'No listings need a statement'})):'';
 return `${cwHeader('CMA Reports','Pick a report, enter the target address and search options, then pick the records to include.')}${tabs}${opts}${pps}
 ${cwCard('Your '+kind+' reports',`<div class="toolbar">${cwSelect('cwPs:cmaag',['Lead Agents',...cwAgentNames()],{label:'Lead agent'})}${cwSelect('cwPs:cmaexp',['Expiry','Active','Expiring soon','Expired'],{label:'Expiry'})}</div>`+cwTable('cwPsCmaR',[['Address',c=>`<b>${h(c.address)}</b>`,c=>c.address],['Agent',c=>h(c.agent)],['Comparables',c=>c.comps.length],['Created',c=>cwDate(c.created),c=>c.created],['Expires',c=>cwDate(c.expiry),c=>c.expiry],['Status',c=>tag(c.status,c.status==='Active'?'green':'')],['',c=>`<div class="cw-row">${cwGoBtn(c.status==='Draft'?'Continue':'Edit','/prospecting/cma/'+c.id,'sm')}${cwBtn('View report','cwPsCmaView',c.id,'sm primary')}${cwBtn('PDF','cwPsCmaPdf',c.id,'sm')}${cwBtn('Delete','cwPsCmaDel',c.id,'sm ghost')}</div>`]],reps,{empty:'No reports yet'}))}`},
 ai(){const a=cwProps().filter(d=>['Appraisal','Proposal'].includes(d.stage)&&!state.cw.cma.some(c=>c.dealId===d.id));const pps=cwProps().filter(d=>d.stage==='For sale'&&!cwDX(d).docs.pps.length);
  return[a.length?{k:'draft',t:a.length+' appraisals without a CMA',b:'GeeVee can start a draft for each with the closest recent sales. You check every comparable before it goes to a vendor.',a:[['Start drafts','cwPsCmaAuto','','primary']]}:null,pps.length?{k:'check',t:pps.length+' listings missing a Property Price Statement',b:'Required before advertising in Victoria. The indicative price cannot be below your estimate, and a range cannot exceed 10%.'}:null]}});
cwOn('cwPsCmaQuick',()=>{const d=new Date();d.setMonth(d.getMonth()-6);cwSetF('cwPs:cmafrom',cwLocalDay(d));cwSetF('cwPs:cmato',cwLocalDay());render()});
function cwPsCmaNew(kind,d,addr){const c={id:cwId('CMA'),kind,address:d?cwAddr(d):addr,dealId:d?.id||null,agent:CW_ME,created:cwNowISO(),expiry:new Date(Date.now()+30*864e5).toISOString(),comps:[],status:'Draft',step:0,filters:{from:cwF('cwPs:cmafrom',''),to:cwF('cwPs:cmato',''),pmin:cwF('cwPs:cmapmin',''),pmax:cwF('cwPs:cmapmax',''),bmin:cwF('cwPs:cmabmin',''),sur:cwF('cwPs:cmasur',true)},low:d?cwDX(d).priceLow:0,high:d?cwDX(d).priceHigh:0};state.cw.cma.unshift(c);return c}
cwOn('cwPsCmaStart',tab=>{const d=findD(cwF('cwPs:cmadeal',''));const addr=cwF('cwPs:cmaaddr','').trim();if(!d&&!addr){toast('Choose a property or enter an address.');return}const c=cwPsCmaNew(CW_PS_CMA_KIND[tab],d,addr);persist();cwGo('/prospecting/cma/'+c.id)});
cwOn('cwPsCmaAuto',()=>{let n=0;for(const d of cwProps().filter(d=>['Appraisal','Proposal'].includes(d.stage)&&!state.cw.cma.some(c=>c.dealId===d.id))){const c=cwPsCmaNew('Sales CMA',d);c.comps=state.cw.sales.filter(s=>cwPsNear(d.suburb,10).includes(s.suburb)).slice(0,3).map(s=>s.id);n++}cwPersist(n+' draft CMAs started. Check each before use.')});
cwOn('cwPsCmaDel',id=>{state.cw.cma=state.cw.cma.filter(c=>c.id!==id);cwPersist('Report deleted.')});
cwOn('cwPsCmaView',id=>cwModal('cwPsCmaView',id));
cwModalDef('cwPsCmaView',id=>{const c=state.cw.cma.find(x=>x.id===id);const cs=state.cw.sales.filter(s=>c.comps.includes(s.id));const rent=c.kind==='Rental CMA';return{title:c.kind+': '+c.address,wide:'large',body:`${cwKV([['Prepared by',h(c.agent)],['Created',cwDate(c.created)],['Expires',cwDate(c.expiry)],[rent?'Estimated rent':'Estimated selling price',c.low?(rent?'$'+Math.round(c.low*0.0032/52*10)/10*10+' to $'+Math.round(c.high*0.0032/52*10)/10*10+' per week':cwMoney(c.low)+' to '+cwMoney(c.high)):'Not set']])}<div class="sep"></div><h3>Comparables</h3>${cs.map(s=>`<div class="list-row"><div class="list-main"><strong>${h(s.address)}, ${h(s.suburb)}</strong><div class="sub">${rent?'$'+Math.round(s.price*0.0032/52)+' per week':cwMoney(s.price)} · ${cwDate(s.date)} · ${s.beds} bed</div></div></div>`).join('')||'<p class="hint">No comparables chosen.</p>'}<p class="hint" style="margin-top:10px">Sample sales data in this prototype. Verify every comparable before giving this to a vendor.</p>`,foot:cwBtn('Print','cwPsPrint','','')+cwBtn('Close','close','','primary')}});
cwOn('cwPsCmaPdf',id=>{const c=state.cw.cma.find(x=>x.id===id);const cs=state.cw.sales.filter(s=>c.comps.includes(s.id));const txt=c.kind+'\n'+c.address+'\n\n'+cs.map(s=>s.address+', '+s.suburb+': '+cwMoney(s.price)+' ('+s.date+')').join('\n');try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'text/plain'}));a.download=c.kind.replace(/\W+/g,'-')+'.txt';document.body.appendChild(a);a.click();a.remove()}catch(e){}toast('Report downloaded. A designed PDF comes from the production report service.')});
cwOn('cwPsPpsMake',id=>{const d=findD(id);const c=state.cw.cma.find(x=>x.dealId===id&&x.kind==='Property Price Statement')||cwPsCmaNew('Property Price Statement',d);persist();cwGo('/prospecting/cma/'+c.id)});
cwPage('/prospecting/cma/:id',{title:'CMA report',group:'prosp',render(ctx){let c=state.cw.cma.find(x=>x.id===ctx.params.id)||(String(ctx.params.id)==='1'?state.cw.cma[0]:null);if(!c)return cwEmpty('Report not found','',cwGoBtn('CMA reports','/prospecting/cma','primary'));
 const d=findD(c.dealId),sub=d?.suburb||(c.address.split(',')[1]||'').trim(),near=cwPsNear(sub,c.filters?.sur===false?2:10);
 const f=c.filters||{};const pool=state.cw.sales.filter(s=>(!f.from||s.date>=f.from)&&(!f.to||s.date<=f.to)&&(!f.pmin||s.price>=Number(f.pmin))&&(!f.pmax||s.price<=Number(f.pmax))&&(!f.bmin||s.beds>=Number(f.bmin)));
 const street=pool.filter(s=>d&&s.address.split(' ').slice(1).join(' ')===d.address.split(' ').slice(1).join(' ')),suburb=pool.filter(s=>s.suburb===sub),surr=pool.filter(s=>near.includes(s.suburb)&&s.suburb!==sub),listings=cwProps().filter(x=>x.stage==='For sale'&&near.includes(x.suburb)&&x.id!==c.dealId);
 const steps=['Results summary','Pick comparables','Price and finish'];const step=c.step||0;const pps=c.kind==='Property Price Statement';
 let body='';
 if(step===0)body=`${cwStats([['Property history',d?cwDX(d).priceEvents.length:0],['Comparable sales (street)',street.length],['Comparable sales (suburb)',suburb.length],['Current listings',listings.length]])}${listings.length?cwNote(listings.length+' result'+(listings.length>1?'s are':' is')+' a current listing. Current listings are shown for context, not used as sales evidence.'):''}<div class="sep"></div>${cwCard('Land and planning',d?cwKV([['Land',cwDX(d).land?cwDX(d).land+' m²':'Not recorded'],['Type',h(cwDX(d).type)],['Bedrooms',String(cwDX(d).beds)],['Year built',String(cwDX(d).year)]]):'<p class="small">Custom address. Use Get property data to fetch land and planning details.</p>',cwBtn('Get property data','cwPsCmaData',c.id,'sm'))}`;
 else if(step===1)body=`<p class="small" style="margin-bottom:10px">Pick the sales to include${pps?'. A Property Price Statement needs the 3 most comparable sales':''}. ${c.comps.length} chosen.</p><div class="cw-ps-list">${[...suburb,...surr].map(s=>`<label class="cw-ps-pick ${c.comps.includes(s.id)?'on':''}"><input type="checkbox" data-cwpscomp="${h(c.id)}|${h(s.id)}" ${c.comps.includes(s.id)?'checked':''}><span><b>${h(s.address)}, ${h(s.suburb)}</b><small>${cwMoney(s.price)} · ${cwDate(s.date)} · ${s.beds} bed ${s.baths} bath</small></span></label>`).join('')||'<p class="hint">No sales match the search options. Refine the search.</p>'}</div>`;
 else{const est=d?cwDX(d).priceLow:0;const chk=cwPsPriceCheck(c,est);body=`${cwForm('cwPsCmaP',[{n:'low',l:pps?'Indicative selling price from ($)':'Estimate from ($)',t:'number',req:true},{n:'high',l:pps?'Indicative selling price to ($)':'Estimate to ($)',t:'number'}],{low:c.low||'',high:c.high||''})}<div style="margin-top:10px">${chk.length?cwNote(chk.map(h).join('<br>'),'warn'):cwNote('Price passes the Victorian checks: not below the agent\'s estimate and a range of no more than 10%.','ok')}</div>`}
 return `${cwHeader(steps[step],'Step '+(step+1)+' of 3 · '+h(c.kind)+' · '+h(c.address),`${cwGoBtn('Refine search','/prospecting/cma','')}${cwBtn('Start again','cwPsCmaReset',c.id,'')}${cwGoBtn('Exit','/prospecting/cma','')}`)}${cwSteps(steps,step)}${cwCard('',body)}
 <div class="cw-row between">${step>0?cwBtn('Back','cwPsCmaStep',c.id+'|-1',''):'<span></span>'}${step<2?cwBtn('Continue','cwPsCmaStep',c.id+'|1','primary'):cwBtn(c.status==='Active'?'Save changes':'Save report','cwPsCmaSave',c.id,'primary')}</div>`},
 ai(ctx){const c=state.cw.cma.find(x=>x.id===ctx.params.id)||state.cw.cma[0];return c?[{k:'auto',t:'GeeVee ranks comparables',b:'Same suburb, similar bedrooms and sales in the last 6 months first. Sample data in this prototype.',a:c.step===1?[['Pick best 3','cwPsCmaBest',c.id,'primary']]:[]},{k:'info',t:'Underquoting rules',b:'The advertised and indicative price cannot be below the agent\'s estimate, the vendor\'s asking price or a rejected written offer. Ranges are 10% at most.'}]:[]}});
function cwPsPriceCheck(c,est){const p=[];const low=Number(c.low)||0,high=Number(c.high)||0;if(!low)return['Enter a price.'];if(high&&high<low)p.push('The upper figure is below the lower figure.');if(high&&(high-low)/low>0.1)p.push('The range is more than 10% of the lower figure.');if(est&&low<est)p.push('The lower figure is below the estimated selling price in the authority ('+cwMoney(est)+').');if(c.kind==='Property Price Statement'&&c.comps.length<3)p.push('A Property Price Statement needs 3 comparable sales ('+c.comps.length+' chosen).');return p}
cwOn('cwPsCmaStep',k=>{const [id,dir]=k.split('|');const c=state.cw.cma.find(x=>x.id===id);if(!c)return;if((c.step||0)===1&&dir==='1'&&!c.comps.length){toast('Pick at least one comparable.');return}c.step=Math.max(0,Math.min(2,(c.step||0)+Number(dir)));cwPersist()});
cwOn('cwPsCmaReset',id=>{const c=state.cw.cma.find(x=>x.id===id);if(!c)return;c.comps=[];c.step=0;cwPersist('Started again.')});
cwOn('cwPsCmaBest',id=>{const c=state.cw.cma.find(x=>x.id===id);const d=findD(c.dealId);const sub=d?.suburb||'';const beds=d?cwDX(d).beds:3;c.comps=state.cw.sales.slice().sort((a,b)=>((a.suburb===sub?0:2)+Math.abs(a.beds-beds))-((b.suburb===sub?0:2)+Math.abs(b.beds-beds))||b.date.localeCompare(a.date)).slice(0,3).map(s=>s.id);cwPersist('GeeVee picked 3. Check each one.')});
cwOn('cwPsCmaData',id=>{const lc=state.cw.landchecker;const c=state.cw.cma.find(x=>x.id===id);if(lc&&lc.on===false){toast('Landchecker lookups are switched off by your admin.');return}if(lc&&lc.calls.length>=lc.limit){toast('Monthly Landchecker limit reached.');return}lc?.calls.unshift({at:cwNowISO(),type:'Property report',by:CW_ME,address:c.address});cwPersist('Property data fetched (simulated). Logged against the Landchecker limit.')});
cwOn('cwPsCmaSave',id=>{const c=state.cw.cma.find(x=>x.id===id);const v=cwRead('cwPsCmaP',[{n:'low',l:'Price',t:'number',req:true},{n:'high',l:'Upper price',t:'number'}]);if(!v)return;c.low=Number(v.low);c.high=Number(v.high)||Number(v.low);const d=findD(c.dealId);const probs=cwPsPriceCheck(c,d?cwDX(d).priceLow:0);if(probs.length){persist();render();toast('Fix the price check first: '+probs[0]);return}
 c.status='Active';c.expiry=new Date(Date.now()+30*864e5).toISOString();if(d){const x=cwDX(d);if(c.kind!=='Rental CMA'&&!x.comps.length)x.comps=state.cw.sales.filter(s=>c.comps.includes(s.id)).slice(0,3).map(s=>[s.address,s.price,'Chosen in CMA '+c.id]);if(c.kind==='Property Price Statement'){x.docs.pps.unshift({id:cwId('DOC'),name:'Property Price Statement - '+d.address+'.pdf',size:'204 KB',at:cwNowISO(),by:CW_ME});x.priceEvents.unshift({at:cwNowISO(),what:'Indicative price in the Property Price Statement',value:cwMoney(c.low)+' to '+cwMoney(c.high)});d.compliance['Property Price Statement']=true}cwPropActivity(d,c.kind+' saved')}
 audit('cma',c.kind+' saved: '+c.address,state.cw.sales.filter(s=>c.comps.includes(s.id)).length+' comparables.');cwPersist(c.kind+' saved.');cwGo('/prospecting/cma')});

/* ---------- AI voice caller, campaign setup, voice agents ---------- */
cwPage('/ai-voice-caller',{title:'AI voice caller',group:'prosp',render(){cwPsEnsure();
 const calls=state.cw.voiceCalls,act=calls.filter(c=>c.status==='Active'),done=calls.filter(c=>c.status!=='Active'),ok=done.filter(c=>c.outcome==='Interested'||c.outcome==='Booked');
 return `${cwHeader('AI Call Center','Simulated AI calling. Every call plays a recording notice first and needs legal sign-off before going live.',`${cwGoBtn('Voice agents','/voice-agents','')}${cwGoBtn('New campaign','/campaign-setup','primary')}`)}
 ${cwNote('<b>Prototype:</b> no real calls are made. In production, AI calls only go to contacts with permission, after a Do Not Call check, inside permitted calling hours, with the recording notice. Legal sign-off is still needed.','warn')}
 ${cwStats([['Calls, past 30 days',done.length],['Active now',act.length],['Success rate',done.length?Math.round(ok.length/done.length*100)+'%':'0%'],['Average length',done.length?'4:32':'0:00']])}
 ${cwCard('<span class="cw-ps-live"></span>Active calls',act.map(c=>`<div class="cw-ps-call"><div class="cw-row between"><b>${h(c.name)} · ${h(c.agent)}</b>${cwBtn('End call','cwPsVcEnd',c.id,'sm')}</div><div class="cw-chat" style="margin-top:8px">${c.lines.map(([w,t])=>`<div class="cw-msg ${w==='ai'?'':'me'}">${h(t)}<small>${w==='ai'?'GeeVee voice':'Contact'}</small></div>`).join('')}</div></div>`).join('')||cwEmpty('No active calls at the moment','',cwBtn('Start a test call','cwPsVcTest','','primary')))}
 ${cwCard('Recent calls',cwTable('cwPsVc',[['Contact',c=>h(c.name)],['Campaign',c=>h(c.agent)],['When',c=>cwDateTime(c.at),c=>c.at],['Outcome',c=>tag(c.outcome||'',c.outcome==='Interested'||c.outcome==='Booked'?'green':'')],['Follow-up',c=>c.task?tag('Call task on Today','teal'):'']],done,{empty:'No calls yet'}))}`},
 ai(){const a=state.cw.voiceAgents.filter(v=>v.status==='Active');return[{k:'check',t:'Legal sign-off needed',b:'Automated calls need consent, a recording notice and calling-hour rules confirmed by Collings\' lawyers before launch.'},a.length?{k:'info',t:a.length+' active campaigns',b:'Interested sellers become a call task for you. The AI never negotiates or quotes a price.'}:{k:'info',t:'No active campaigns',a:[['Set one up','cwGo','/campaign-setup','primary']]}]}});
function cwPsVcTargets(type){return cwContacts().filter(p=>!cwOptedOut(p)&&(type==='Seller'?['seller','both'].includes(p.role):type==='Buyer'?p.role!=='seller':true))}
cwOn('cwPsVcTest',()=>{const p=cwPsVcTargets('Buyer')[0];state.cw.voiceCalls.unshift({id:cwId('VC'),name:p?.name||'Test contact',contactId:p?.id||'',agent:'Test call',status:'Active',at:cwNowISO(),lines:[['ai','Hi, this is GeeVee, an AI assistant calling for Collings Real Estate. This call is recorded. Is now a good time?'],['user','Sure, what is it about?'],['ai','You enquired about homes in Coburg. Would you like Caleb to call you about a new listing?']]});cwPersist('Test call started (simulated).')});
cwOn('cwPsVcEnd',id=>{const c=state.cw.voiceCalls.find(x=>x.id===id);if(!c)return;c.status='Completed';c.outcome=cwPick(id,['Interested','Not interested','Voicemail','Interested']);if(c.outcome==='Interested'&&c.contactId){addTask({title:'Call '+c.name+' after AI call: interested',contactId:c.contactId,dealId:'',due:'Today',priority:'High',category:'Call',origin:'GeeVee · AI call'});c.task=true}cwPersist('Call ended: '+c.outcome+'.')});

const CW_PS_SETUP=[['Basic information',[{n:'name',l:'Agent name',req:true},{n:'type',l:'Agent type',t:'select',o:['Buyer','Seller','General'],req:true},{n:'tone',l:'Voice tone',t:'select',o:['Friendly','Professional','Casual','Formal','Enthusiastic'],req:true},{n:'desc',l:'Description',t:'textarea'}]],['Calling schedule',[{n:'start',l:'Start time',t:'time',req:true},{n:'end',l:'End time',t:'time',req:true},{n:'mon',l:'Monday',t:'check'},{n:'tue',l:'Tuesday',t:'check'},{n:'wed',l:'Wednesday',t:'check'},{n:'thu',l:'Thursday',t:'check'},{n:'fri',l:'Friday',t:'check'},{n:'sat',l:'Saturday',t:'check'},{n:'sun',l:'Sunday',t:'check'}]],['Performance settings',[{n:'throttle',l:'Call throttle limit (calls per hour)',t:'number',req:true},{n:'notice',l:'A recording notice plays at the start of every call',t:'check',req:true},{n:'dnc',l:'Check the Do Not Call Register before each call',t:'check',req:true},{n:'legal',l:'Legal sign-off received for this campaign',t:'check',help:'Without it the agent can be saved but not activated.'}]]];
cwPage('/campaign-setup',{title:'Campaign setup',group:'prosp',render(ctx){cwPsEnsure();const s=state.cw.psSetup;if(ctx.q.edit&&s.editId!==ctx.q.edit){const v=state.cw.voiceAgents.find(x=>x.id===ctx.q.edit);if(v){s.editId=v.id;s.step=0;s.v={...v}}}
 const [title,fields]=CW_PS_SETUP[s.step];
 return `${cwHeader('Campaign Setup','Configure your AI campaign in easy steps.',`${s.step>0?cwBtn('Previous','cwPsSetupStep','-1',''):''}${cwBtn(s.step<2?'Save & Next':'Save campaign','cwPsSetupStep','1','primary')}`)}
 ${cwSteps(CW_PS_SETUP.map(x=>x[0]),s.step)}${cwCard('Campaign details: '+title,cwForm('cwPsSet'+s.step,fields,{start:'09:00',end:'17:00',mon:true,tue:true,wed:true,thu:true,fri:true,throttle:20,tone:'Friendly',type:'Seller',...s.v}))}
 ${cwBtn('Cancel setup','cwPsSetupCancel','','ghost')}`},
 ai(){return[{k:'info',t:'Permitted calling hours',b:'Telemarketing hours in Australia are limited (weekdays 9am to 8pm, Saturday 9am to 5pm, no Sundays or public holidays). GeeVee stops calls outside them.'},{k:'check',t:'Seller campaigns',b:'An AI call can ask if an owner wants to talk. Any interest becomes a call from you. The AI never quotes a price.'}]}});
cwOn('cwPsSetupStep',dir=>{const s=state.cw.psSetup;if(dir==='1'){const v=cwRead('cwPsSet'+s.step,CW_PS_SETUP[s.step][1]);if(!v)return;Object.assign(s.v,v);if(s.step===1&&v.end<=v.start){cwU().err['cwPsSet1']={end:'End time must be after the start time.'};cwU().draft['cwPsSet1']=v;render();return}
  if(s.step===2){const v2=s.v;const rec={name:v2.name,type:v2.type,tone:v2.tone,desc:v2.desc,start:v2.start,end:v2.end,days:['mon','tue','wed','thu','fri','sat','sun'].filter(k=>v2[k]),throttle:Number(v2.throttle),notice:v2.notice,dnc:v2.dnc,legal:v2.legal};
   if(s.editId)Object.assign(state.cw.voiceAgents.find(x=>x.id===s.editId)||{},rec);else state.cw.voiceAgents.push({id:cwId('VA'),...rec,status:'Paused',calls:0,success:0,created:cwNowISO()});
   audit('voice','Voice agent saved: '+rec.name,rec.legal?'Legal sign-off recorded.':'Saved paused, legal sign-off missing.');state.cw.psSetup={step:0,v:{}};persist();cwGo('/voice-agents');toast('Voice agent saved, paused until you activate it.');return}
  s.step++}else s.step=Math.max(0,s.step-1);cwPersist()});
cwOn('cwPsSetupCancel',()=>{state.cw.psSetup={step:0,v:{}};persist();cwGo('/voice-agents')});
cwPage('/voice-agents',{title:'Voice agents',group:'prosp',render(){cwPsEnsure();const va=state.cw.voiceAgents;
 return `${cwHeader('Voice Agents','Your AI calling agents and how they perform. Simulated in this prototype.',cwGoBtn('Create voice agent','/campaign-setup','primary'))}
 ${cwStats([['Total agents',va.length],['Active agents',va.filter(v=>v.status==='Active').length],['Total calls',va.reduce((a,v)=>a+v.calls,0)],['Avg success rate',va.length&&va.some(v=>v.calls)?Math.round(va.reduce((a,v)=>a+v.success,0)/Math.max(1,va.reduce((a,v)=>a+v.calls,0))*100)+'%':'0%']])}
 ${va.length?`<div class="cw-cards">${va.map(v=>`<div class="cw-pcard"><div class="body"><div class="cw-row between"><h3>${h(v.name)}</h3>${tag(v.status,v.status==='Active'?'green':'')}</div><div class="meta">${h(v.type)} · ${h(v.tone)} · ${h(v.start)} to ${h(v.end)} · ${v.days.length} days · ${v.throttle} calls per hour</div><p class="small">${h(v.desc||'')}</p><div class="cw-row">${v.notice?tag('Recording notice','teal'):tag('No recording notice','red')}${v.legal?tag('Legal sign-off','green'):tag('Legal sign-off missing','yellow')}</div><div class="meta">${v.calls} calls · ${v.success} interested</div><div class="acts">${v.status==='Active'?cwBtn('Pause','cwPsVaToggle',v.id,'sm')+cwBtn('Run calls now','cwPsVaRun',v.id,'sm primary'):cwBtn('Activate','cwPsVaToggle',v.id,'sm primary')}${cwGoBtn('Edit','/campaign-setup?edit='+v.id,'sm')}${cwBtn('Delete','cwPsVaDel',v.id,'sm ghost')}</div></div></div>`).join('')}</div>`:cwEmpty('No voice agents found','Create one to start a simulated AI calling campaign.',cwGoBtn('Create voice agent','/campaign-setup','primary'))}`},
 ai(){const p=state.cw.voiceAgents.filter(v=>!v.legal||!v.notice);return[p.length?{k:'check',t:p.length+' agents cannot go live',b:'They need a recording notice and legal sign-off before activation.'}:{k:'info',t:'Calls are simulated',b:'Interested contacts become call tasks on Today.'}]}});
cwOn('cwPsVaToggle',id=>{const v=state.cw.voiceAgents.find(x=>x.id===id);if(!v)return;if(v.status!=='Active'&&(!v.legal||!v.notice||!v.dnc)){toast('Cannot activate: recording notice, Do Not Call check and legal sign-off are all required.');return}v.status=v.status==='Active'?'Paused':'Active';audit('voice','Voice agent '+v.status.toLowerCase()+': '+v.name,'Simulated.');cwPersist(v.name+' '+v.status.toLowerCase()+'.')});
cwOn('cwPsVaRun',id=>{const v=state.cw.voiceAgents.find(x=>x.id===id);if(!v||v.status!=='Active')return;const hr=new Date().getHours(),day=['sun','mon','tue','wed','thu','fri','sat'][new Date().getDay()];
 const targets=cwPsVcTargets(v.type).filter(p=>!state.cw.voiceCalls.some(c=>c.contactId===p.id&&c.agent===v.name)).slice(0,Math.min(5,v.throttle));let ok=0;
 for(const p of targets){const out=cwPick(p.id+v.id,['Interested','Not interested','Voicemail','No answer','Interested']);const c={id:cwId('VC'),name:p.name,contactId:p.id,agent:v.name,status:'Completed',at:cwNowISO(),outcome:out,lines:[]};if(out==='Interested'){addTask({title:'Call '+p.name+': interested after AI call ('+v.name+')',contactId:p.id,dealId:'',due:'Today',priority:'High',category:'Call',origin:'GeeVee · AI call'});c.task=true;ok++}state.cw.voiceCalls.unshift(c)}
 v.calls+=targets.length;v.success+=ok;cwPersist(targets.length+' simulated calls, '+ok+' interested. '+(v.days.includes(day)&&hr>=parseInt(v.start)&&hr<parseInt(v.end)?'':'Outside the schedule, so production would wait.'))});
cwOn('cwPsVaDel',id=>cwConfirm('Delete this voice agent?','Its call history is kept.','cwPsVaDelYes',id,'Delete','warn'));
cwOn('cwPsVaDelYes',id=>{state.cw.voiceAgents=state.cw.voiceAgents.filter(x=>x.id!==id);ui.modal=null;cwPersist('Voice agent deleted.')});

/* ---------- Campaign manager ---------- */
cwPage('/campaign-manager',{title:'Campaign manager',group:'prosp',render(){cwPsEnsure();const q=cwF('cwPs:cmq','');const list=cwSearchRows(cwProps().filter(d=>['For sale','Listed'].includes(d.stage)),q,d=>d.address+' '+d.suburb);
 return `${cwHeader('Campaign Manager','Manage marketing campaigns and third-party integrations.',cwBtn('Create campaign','cwPsCmStart','','primary'))}
 <div class="toolbar">${cwInput('cwPs:cmq','Search properties by address or suburb')}</div>
 ${cwCard('Active properties '+tag(list.length+'','teal'),cwTable('cwPsCm',[['Property',d=>`<div class="cw-row"><div class="cw-thumb">${cwDX(d).beds} bed</div><div><b>${h(d.address)}, ${h(d.suburb)}</b><div class="tiny muted">${cwPrice(d)} · ${h(d.stage)}</div></div></div>`,d=>d.address],['Campaign',d=>{const c=state.cw.campaignsMkt[d.id];return c?tag(c.status,'green')+`<div class="tiny muted">${h(c.channels.join(', '))} · ${cwMoney(c.budget)}</div>`:tag('Not started','')}],['Orders',d=>state.cw.psOrders.filter(o=>o.dealId===d.id).map(o=>tag(o.item,'outline')).join(' ')||'<span class="muted">None</span>'],['',d=>`<div class="cw-row">${cwGoBtn('Property details','/properties/'+d.id,'sm')}${state.cw.campaignsMkt[d.id]?'':cwBtn('Start campaign','cwPsCmStart',d.id,'sm primary')}${cwBtn('Email buyers','cwPsCmBuyers','Email|'+d.id,'sm')}${cwBtn('SMS buyers','cwPsCmBuyers','SMS|'+d.id,'sm')}${cwBtn('Order board & brochures','cwPsCmOrder',d.id,'sm')}</div>`]],list,{empty:'No active properties'}))}`},
 ai(){const n=cwProps().filter(d=>['For sale','Listed'].includes(d.stage)&&!state.cw.campaignsMkt[d.id]);return[n.length?{k:'check',t:n.length+' listings without a campaign',b:'Marketing spend is the vendor\'s decision. Record the agreed budget before starting.'}:null,{k:'draft',t:'Buyer emails and texts',b:'GeeVee drafts one message per matched buyer and puts them on Today. Opted-out buyers and buyers with a live offer are left out.'}]}});
const CW_PS_CM_FIELDS=[{n:'dealId',l:'Property',t:'select',req:true,o:[]},{n:'budget',l:'Vendor-approved budget ($)',t:'number',req:true},{n:'rea',l:'realestate.com.au',t:'check'},{n:'domain',l:'Domain',t:'check'},{n:'social',l:'Social ads',t:'check'},{n:'portal',l:'Collings off-market portal',t:'check'},{n:'approved',l:'The vendor approved this budget in writing',t:'check',req:true}];
cwOn('cwPsCmStart',id=>cwModal('cwPsCm',id||''));
cwModalDef('cwPsCm',id=>({title:'Start campaign',body:cwForm('cwPsCmF',CW_PS_CM_FIELDS.map(f=>f.n==='dealId'?{...f,o:[['','Choose a property'],...cwProps().filter(d=>['For sale','Listed'].includes(d.stage)&&!state.cw.campaignsMkt[d.id]).map(d=>[d.id,cwAddr(d)])]}:f),{dealId:id,rea:true,domain:true}),foot:cwBtn('Cancel','close')+cwBtn('Start campaign','cwPsCmSave','','primary')}));
cwOn('cwPsCmSave',()=>{const v=cwRead('cwPsCmF',CW_PS_CM_FIELDS);if(!v)return;const d=findD(v.dealId);const ch=[v.rea&&'realestate.com.au',v.domain&&'Domain',v.social&&'Social ads',v.portal&&'Off-market portal'].filter(Boolean);if(!ch.length){toast('Choose at least one channel.');return}const pc=d.stage==='For sale'?cwPsPriceCheck({low:cwDX(d).priceLow,high:cwDX(d).priceHigh,kind:'',comps:[]},cwDX(d).priceLow):[];if(pc.length){toast('Price check failed: '+pc[0]);return}
 state.cw.campaignsMkt[d.id]={status:'Live (simulated)',channels:ch,budget:Number(v.budget),at:cwNowISO()};cwPropActivity(d,'Campaign started: '+ch.join(', '));audit('campaign','Campaign started: '+d.address,'Budget '+cwMoney(v.budget)+', vendor approved. Simulated, no portal upload.');ui.modal=null;cwPersist('Campaign started (simulated).')});
cwOn('cwPsCmBuyers',k=>{const [type,id]=k.split('|');const d=findD(id);if(!cwPsLive(d)){toast('Not advertised yet, so no buyer marketing.');return}const ms=typeof gvxMatchBuyers==='function'?gvxMatchBuyers(d):[];let n=0;for(const m of ms){if(!m.ok||m.liveOffer)continue;if(state.actions.some(a=>a.contactId===m.p.id&&a.dealId===d.id&&a.status==='Awaiting review'))continue;const dr=gvxBuyerDraft(m.p,d,type);addAction({type,title:type+' to '+m.p.name+' about '+d.address,body:dr.body,contactId:m.p.id,dealId:d.id,tier:'A2'});n++}cwPersist(n?n+' '+type.toLowerCase()+' drafts on Today for approval. Nothing was sent.':'No eligible buyers with a recorded reason to hear about this property.')});
const CW_PS_ORDER=[{n:'item',l:'Item',t:'select',o:['Signboard','Brochures (100)','Photography','Floor plan','Drone video','Window card'],req:true},{n:'supplier',l:'Supplier',t:'select',o:['Collings preferred supplier','Other supplier']},{n:'date',l:'Needed by',t:'date',req:true},{n:'note',l:'Instructions',t:'textarea'}];
cwOn('cwPsCmOrder',id=>cwModal('cwPsCmOrder',id));
cwModalDef('cwPsCmOrder',id=>({title:'Order board & brochures',body:cwForm('cwPsOr',CW_PS_ORDER,{date:cwLocalDay(new Date(Date.now()+3*864e5))})+`<div style="margin-top:10px">${state.cw.psOrders.filter(o=>o.dealId===id).map(o=>`<div class="list-row"><div class="list-main"><strong>${h(o.item)}</strong><div class="sub">${h(o.supplier)} · needed ${cwDate(o.date)} · ${h(o.status)}</div></div></div>`).join('')}</div>`,foot:cwBtn('Close','close')+cwBtn('Place order','cwPsCmOrderSave',id,'primary')}));
cwOn('cwPsCmOrderSave',id=>{const v=cwRead('cwPsOr',CW_PS_ORDER);if(!v)return;state.cw.psOrders.push({id:cwId('OR'),dealId:id,...v,status:'Ordered (simulated)',at:cwNowISO()});cwPropActivity(findD(id),'Ordered '+v.item);persist();cwModal('cwPsCmOrder',id);toast(v.item+' ordered (simulated). The cost is billed to the vendor\'s campaign.')});
